INSERT INTO `competencia` (`id`, `id_rama`, `id_area`, `numero`, `descripcion`) VALUES
(1, 1, 1, 1, 'Elijo alimentos que me ayudan a crecer, estar sano y fuerte.'),
(2, 1, 1, 2, 'Mantengo una buena higiene personal para tener una vida saludable.'),
(3, 1, 1, 3, 'Reconozco mis emociones y las expreso entendiendo cómo influyen en mí y en las demás personas.'),
(4, 1, 1, 4, 'Cuestiono los modelos de cuerpos que veo en los medios de comunicación, en la publicidad, en el deporte y el espectáculo.'),
(5, 1, 1, 5, 'Valoro y cuido mi cuerpo tal como es para estar saludable y evito comparaciones con el cuerpo de las demás.'),
(6, 1, 1, 6, 'Expreso mis afectos de manera clara y respetuosa con mis familiares, amigas y amigos.'),
(7, 1, 1, 7, 'Cuido mi privacidad e intimidad y respeto la de las demás personas.'),
(8, 1, 1, 8, 'Evito hacer cosas que puedan lastimarme a mi o a otras personas.'),
(9, 1, 1, 9, 'Me gustan las actividades deportivas y recreativas que comparto con mis amigas y amigos, donde me divierto y juego.'),
(10, 1, 1, 10, 'Conozco acerca de mi cuerpo (órganos y sistemas), sus funciones y entiendo que es importante cuidar de ellos para sentirme bien.'),
(11, 1, 2, 11, 'Ante una pelea o situación de conflicto recurro al diálogo para resolverla.'),
(12, 1, 2, 12, 'Me intereso por la cultura de mi comunidad y mi país.'),
(13, 1, 2, 13, 'Respeto las diversas tradiciones y expresiones culturales de las colectividades que conforman mi comunidad.'),
(14, 1, 2, 14, 'Conozco mi historia, la de mi familia y de mi país.'),
(15, 1, 2, 15, 'Conozco mis derechos como niña o niño e identifico cuando estos son vulnerados.'),
(16, 1, 2, 16, 'Participo de las decisiones que me involucran y respeto los acuerdos que realizamos.'),
(17, 1, 2, 17, 'Comprendo y acepto las reglas y expreso mi opinión sobre ellas.'),
(18, 1, 2, 18, 'Participo e incluyo a todas las personas sin discriminarlas.'),
(19, 1, 2, 19, 'Realizo acciones solidarias para ayudar a las personas que lo necesitan y mejorar los lugares en donde vivo.'),
(20, 1, 2, 20, 'Observo mi entorno con atención para conocer más sobre los problemas que afectan a las personas y sus causas.'),
(21, 1, 2, 21, 'Hablo con los demás sobre lo que creo y respeto lo que las otras personas creen.'),
(22, 1, 2, 22, 'Comprendo que mis creencias se tienen que notar por la forma en que actúo y soy con las demás personas.'),
(23, 1, 2, 23, 'Intento vivir la Ley de la Manada en mis acciones cotidianas.'),
(24, 1, 3, 24, 'Cuido del planeta utilizando los recursos de forma responsable sin desperdiciar.'),
(25, 1, 3, 25, 'Colaboro con otras personas en acciones de cuidado del planeta.'),
(26, 1, 3, 26, 'Identifico algunos problemas ambientales de mi comunidad y las causas que los provocan.'),
(27, 1, 3, 27, 'Comprendo que en la naturaleza todo está relacionado y me comprometo a realizar acciones para mantenerla saludable y en equilibrio.'),
(28, 1, 3, 28, 'Entiendo que mis acciones tienen un impacto en el Planeta Tierra y me comprometo a su cuidado.'),
(29, 1, 3, 29, 'Disfruto de descubrir la diversidad que existe en la naturaleza.'),
(30, 1, 3, 30, 'Desarrollo habilidades que me permiten disfrutar de la naturaleza.'),
(31, 1, 3, 31, 'Descubro las maravillas de la naturaleza y me asombro por la grandeza y belleza que me rodea.'),
(32, 1, 4, 32, 'Me intereso por aprender cosas nuevas.'),
(33, 1, 4, 33, 'Utilizo diferentes herramientas y busco soluciones para resolver situaciones cotidianas.'),
(34, 1, 4, 34, 'Me enfrento a desafíos y problemas y encuentro soluciones creativas para resolverlos.'),
(35, 1, 4, 35, 'Conozco diferentes profesiones y oficios.'),
(36, 1, 4, 36, 'Descubro mis intereses y habilidades realizando pasatiempos y especialidades.'),
(37, 1, 4, 37, 'Me responsabilizo por distintas tareas en mi Manada y seisena.'),
(38, 1, 4, 38, 'Desempeño el rol de seisenera o seisenero y apoyo a otras lobeznas y otros lobatos para que lo hagan.'),
(39, 1, 4, 39, 'Uso programas y aplicaciones que me ayudan en mi vida cotidiana.'),
(40, 1, 4, 40, 'Busco información en diferentes fuentes y me aseguro de que sea útil y verdadera antes de usarla o compartirla.'),
(41, 1, 4, 41, 'Soy responsable en el uso de los dispositivos tecnológicos y los utilizo de manera segura.'),
(42, 1, 4, 42, 'Sé usar el dinero y utilizar mis recursos de manera responsable.'),
(43, 1, 4, 43, 'Organizo mis tiempos en las distintas actividades y responsabilidades, teniendo en cuenta mi tiempo libre y de juego.'),
(44, 1, 4, 44, 'Me propongo tareas que ayudan a superar mis dificultades.'),
(45, 1, 4, 45, 'Pido ayuda y también ayudo a los demás para enfrentar algunas dificultades.'),
(46, 1, 4, 46, 'Expreso mis ideas de forma clara y amable, y escucho a los demás con atención y respeto.'),
(47, 1, 4, 47, 'Expreso mis emociones y sentimientos de diversos medios artísticos.'),
(48, 2, 1, 1, 'Incorporo hábitos de higiene.'),
(49, 2, 1, 2, 'Entiendo la importancia de alimentarme de forma saludable.'),
(50, 2, 1, 3, 'Reconozco y expreso mis emociones, entendiendo cómo me afectan a mí y a las demás personas.'),
(51, 2, 1, 4, 'Soy crítica/o con las imágenes y mensajes que los medios de comunicación y las redes sociales nos presentan sobre los modelos corporales y las modas.'),
(52, 2, 1, 5, 'Busco información y tomo decisiones conscientes para cuidar mi salud y sentirme bien conmigo misma/o.'),
(53, 2, 1, 6, 'Acepto y valoro mi cuerpo y el de los demás, evitando comparaciones.'),
(54, 2, 1, 7, 'Reconozco e identifico las particularidades, diferencias y cambios de mi cuerpo a medida que voy creciendo.'),
(55, 2, 1, 8, 'Identifico y respeto mis emociones y sentimientos vinculados a la sexualidad y sus cambios.'),
(56, 2, 1, 9, 'Valoro el diálogo y el respeto mutuo en mis relaciones, expresando mi opinión de manera segura y respetuosa.'),
(57, 2, 1, 10, 'Conozco los recursos y lugares donde puedo obtener información y apoyo para proteger mis derechos sexuales.'),
(58, 2, 1, 11, 'Descubro los beneficios que tiene la actividad física y los deportes para mi bienestar físico y emocional.'),
(59, 2, 1, 12, 'Trabajo en equipo y disfruto de las actividades físicas y deportivas, fomentando el desarrollo social y emocional.'),
(60, 2, 1, 13, 'Identifico situaciones de riesgo y adopto prácticas seguras.'),
(61, 2, 1, 14, 'Conozco y construyo redes de apoyo y ayuda mutua.'),
(62, 2, 2, 15, 'Colaboro en la resolución de situaciones de conflicto a través del diálogo, evitando situaciones de violencia, en los espacios donde me desenvuelvo.'),
(63, 2, 2, 16, 'Exploro y me identifico con la cultura de mi comunidad y de mi país proponiendo actividades y proyectos con esta temática.'),
(64, 2, 2, 17, 'Valoro mi historia e identidad, la de mi País y respeto sus símbolos patrios.'),
(65, 2, 2, 18, 'Valoro y respeto la importancia de los Derechos Humanos en la sociedad e identifico situaciones de vulneración de estos, buscando activamente ayuda en mi entorno.'),
(66, 2, 2, 19, 'Ejercito y promuevo prácticas que fomenten la participación democrática en los diferentes contextos en donde me desenvuelvo.'),
(67, 2, 2, 20, 'Respeto los acuerdos de convivencia y las decisiones tomadas por los demás, expresando mis propias ideas y posturas de manera empática y respetuosa.'),
(68, 2, 2, 21, 'Promuevo que se garanticen los derechos de todas las personas en los ámbitos en los que participo.'),
(69, 2, 2, 22, 'Fomento el respeto a la diversidad en todas sus formas, cuestionando estereotipos y prejuicios en mis interacciones diarias.'),
(70, 2, 2, 23, 'Promuevo la participación e inclusión de todas las personas, sin discriminación alguna.'),
(71, 2, 2, 24, 'Identifico oportunidades para ayudar a alguien de manera individual y/o colectiva, sin esperar nada a cambio.'),
(72, 2, 2, 25, 'Me comprometo y animo a otras personas a trabajar en conjunto para lograr un cambio positivo en el mundo.'),
(73, 2, 2, 26, 'Observo lo que pasa a mi alrededor y trato de entender las razones detrás de las desigualdades que veo, actuando de manera responsable en situaciones que afectan a la sociedad, contribuyendo a mejorar el bienestar de las personas.'),
(74, 2, 2, 27, 'Me pregunto sobre el origen, la grandeza, belleza y misterios de todo lo que soy, somos y nos rodea.'),
(75, 2, 2, 28, 'Dialogo con los demás sobre lo que creo y busco conocer lo que los otros creen, demostrando respeto e interés.'),
(76, 2, 2, 29, 'Adhiero a los valores expresados en la Ley y la Promesa Scout comprendiendo su importancia para mi vida.'),
(77, 2, 2, 30, 'Me pregunto sobre mis creencias, prioridades, valores y cómo se manifiesta en mi actuar cotidiano.'),
(78, 2, 3, 31, 'Reconozco mi impacto en el ambiente y en la sociedad, adoptando un estilo de vida responsable y sostenible.'),
(79, 2, 3, 32, 'Utilizo los recursos naturales de forma consciente y busco alternativas que promuevan la conservación del ambiente.'),
(80, 2, 3, 33, 'Participo de iniciativas para construir una sociedad más respetuosa con el planeta.'),
(81, 2, 3, 34, 'Comprendo las causas y consecuencias del impacto ambiental y realizo acciones para preservar y proteger el ambiente.'),
(82, 2, 3, 35, 'Comprendo que todo lo que le hacemos a los seres vivos y al ambiente nos afecta recíprocamente.'),
(83, 2, 3, 36, 'Entiendo que la Tierra es un lugar precioso y único en el universo, y que todos tenemos la responsabilidad de protegerla y mantenerla saludable.'),
(84, 2, 3, 37, 'Exploro oportunidades junto a mis amigas y amigos para conectarme con la naturaleza, cuidándola y protegiéndola, ya sea en mi comunidad local o en lugares más lejanos.'),
(85, 2, 3, 38, 'Desarrollo habilidades y técnicas que me permitan el disfrute de la vida en la naturaleza.'),
(86, 2, 3, 39, 'Exploro y contemplo la naturaleza como un espacio que me permite el bienestar para mí, ayudándome a conectar con lo trascendente.'),
(87, 2, 4, 40, 'Exploro temas de mi interés con la intención de mejorar cada día.'),
(88, 2, 4, 41, 'Experimento diferentes medios y tecnologías que me ayuden a resolver problemas de la vida cotidiana.'),
(89, 2, 4, 42, 'Aplico mi conocimiento y habilidades para resolver los desafíos y oportunidades que se me presentan.'),
(90, 2, 4, 43, 'Comparto mis pasatiempos y especialidades con amigas y amigos, buscando intereses comunes que podamos desarrollar en conjunto.'),
(91, 2, 4, 44, 'Asumo un rol de manera responsable en los proyectos y/o actividades de mi Patrulla y/o Unidad.'),
(92, 2, 4, 45, 'Lidero actividades y proyectos, acompañando y motivando a mis pares a sumarse.'),
(93, 2, 4, 46, 'Exploro y experimento con diferentes técnicas y tecnologías para resolver problemas, lograr mis objetivos y descubrir soluciones creativas.'),
(94, 2, 4, 47, 'Busco información en diversas fuentes, y evalúo su veracidad y relevancia antes de aplicarla de manera crítica y creativa en diferentes situaciones y contextos.'),
(95, 2, 4, 48, 'Comprendo la importancia de ser responsable y ético en el uso de la tecnología y la información.'),
(96, 2, 4, 49, 'Administro mis recursos y mi dinero de forma responsable.'),
(97, 2, 4, 50, 'Organizo mi tiempo en forma adecuada diferenciando mis responsabilidades de mi tiempo libre.'),
(98, 2, 4, 51, 'Enfrento y supero las dificultades que se me presentan y aprendo de la experiencia.'),
(99, 2, 4, 52, 'Desarrollo habilidades para comunicarme claramente con otros; escuchar y valorar sus ideas, trabajando juntos para lograr nuestras metas.'),
(100, 2, 4, 53, 'Participo de diferentes manifestaciones artísticas en las que expreso mis emociones y sentimientos.'),
(101, 3, 1, 1, 'Adopto y promuevo hábitos de alimentación e higiene saludables.'),
(102, 3, 1, 2, 'Expreso mis emociones entendiendo cómo me afectan a mí e influyen en mi entorno.'),
(103, 3, 1, 3, 'Adopto una mirada crítica sobre las imágenes y mensajes que los medios de comunicación y las redes sociales nos muestran acerca de los cuerpos y las apariencias.'),
(104, 3, 1, 4, 'Acepto mi cuerpo tal y como es, sin compararlo con el de las demás personas, entendiendo que es único y valioso.'),
(105, 3, 1, 5, 'Respeto y promuevo el respeto sobre la diversidad de identidades y géneros, sin prejuicios ni discriminación.'),
(106, 3, 1, 6, 'Comprendo que mi sexualidad es una parte importante de mi vida individual y junto a otras personas.'),
(107, 3, 1, 7, 'Me informo y tomo decisiones responsables sobre mi salud sexual, cuidando de mí y de las demás personas, para disfrutar de relaciones sanas y seguras.'),
(108, 3, 1, 8, 'Valoro el diálogo y respeto mutuo para mantener relaciones de confianza y afecto.'),
(109, 3, 1, 9, 'Sé a dónde recurrir para proteger mis derechos sexuales y reproductivos obteniendo los recursos necesarios para vivir mi sexualidad con responsabilidad.'),
(110, 3, 1, 10, 'Me involucro en actividades físicas y deportivas como parte fundamental de mi bienestar, explorando mi potencial y desafiándome a mí mismo/a.'),
(111, 3, 1, 11, 'Comparto actividades recreativas, deportivas y lúdicas, fomentando mi desarrollo social y emocional junto a mis amistades.'),
(112, 3, 1, 12, 'Tomo decisiones responsables evitando acciones que puedan poner en riesgo mi seguridad y bienestar, así como el de las personas que me rodean.'),
(113, 3, 1, 13, 'Me informo y preparo para enfrentar situaciones de emergencia.'),
(114, 3, 1, 14, 'Conozco, construyo y promuevo redes de apoyo y ayuda mutua junto a mis pares.'),
(115, 3, 2, 15, 'Contribuyo pacíficamente a la resolución de conflictos evitando toda forma de intolerancia y violencia.'),
(116, 3, 2, 16, 'Valoro mi historia e identidad y promuevo la herencia cultural de mi comunidad y país (costumbres, leyendas, danzas, mitos, artesanías, tradiciones).'),
(117, 3, 2, 17, 'Desarrollo estrategias para promover y difundir los Derechos Humanos.'),
(118, 3, 2, 18, 'Trabajo activamente para facilitar y promover la participación e inclusión de todas las personas en mis actividades.'),
(119, 3, 2, 19, 'Me involucro de forma empática y activa, en acciones solidarias en la comunidad.'),
(120, 3, 2, 20, 'Me preocupo por las personas que me rodean, sus necesidades y busco maneras de hacer una diferencia positiva en sus vidas.'),
(121, 3, 2, 21, 'Ejercito plena y responsablemente mis derechos como ciudadano y los promuevo en todos los ámbitos en donde me desarrollo, con una mirada crítica de la realidad.'),
(122, 3, 2, 22, 'Fomento ámbitos de participación democráticos, respetando las decisiones tomadas sin renunciar a mi derecho a luchar por su cambio.'),
(123, 3, 2, 23, 'Defiendo colectivamente los Derechos de las infancias, juventudes y mujeres y promuevo acciones que contribuyan a garantizarlos.'),
(124, 3, 2, 24, 'Cuestiono mis prejuicios y estereotipos culturales entendiendo cómo estos influyen en las interacciones con otras personas.'),
(125, 3, 2, 25, 'Identifico y analizo los factores que contribuyen a la existencia de problemas sociales, desarrollando una actitud crítica, actuando de manera coherente y responsable en mi entorno.'),
(126, 3, 2, 26, 'Me cuestiono sobre las posturas respecto al origen, la grandeza, belleza y misterios de todo lo que soy, somos y nos rodea.'),
(127, 3, 2, 27, 'Dialogo con las demás personas sobre lo que creo, promoviendo el entendimiento.'),
(128, 3, 2, 28, 'Reconozco cómo mis creencias, prioridades y valores influyen en mis decisiones cotidianas para vivir de manera auténtica y coherente con lo que creo y valoro.'),
(129, 3, 3, 29, 'Adopto un estilo de vida responsable y sostenible en mi consumo y producción.'),
(130, 3, 3, 30, 'Me posiciono de manera crítica y responsable sobre las decisiones con impacto ambiental y realizo acciones al respecto.'),
(131, 3, 3, 31, 'Soy consciente sobre la conexión e interdependencia entre todos los seres vivos, esforzándome por vivir en armonía.'),
(132, 3, 3, 32, 'Entiendo que la Tierra es nuestra casa común y que tenemos la responsabilidad de protegerla para las generaciones presentes y futuras.'),
(133, 3, 3, 33, 'Descubro y valoro la belleza y diversidad de la naturaleza disfrutando de las aventuras que puedo vivir en ella.'),
(134, 3, 3, 34, 'Aprovecho toda oportunidad como un desafío para conectar con el mundo natural, cuidándolo y protegiéndolo.'),
(135, 3, 3, 35, 'Reconozco a la naturaleza como una fuente de bienestar para mí y de conexión con lo trascendente.'),
(136, 3, 4, 36, 'Trabajo en mi superación personal, enfocándome en mis intereses personales.'),
(137, 3, 4, 37, 'Investigo y desarrollo distintas habilidades y tecnologías, que me permitan adquirir experiencias prácticas y útiles para mi vida.'),
(138, 3, 4, 38, 'Afronto creativamente los desafíos y problemas que se me presentan y aporto soluciones innovadoras.'),
(139, 3, 4, 39, 'Me informo, exploro y experimento sobre las distintas opciones dentro del mundo del trabajo en función a mis intereses.'),
(140, 3, 4, 40, 'Motivo y oriento a otras personas a trabajar en conjunto para lograr objetivos comunes.'),
(141, 3, 4, 41, 'Apoyo a otras personas para colaborar en el desarrollo de su liderazgo.'),
(142, 3, 4, 42, 'Aplico técnicas y tecnologías disponibles en la vida cotidiana.'),
(143, 3, 4, 43, 'Busco y evalúo el valor de diversas fuentes de información (académicas, científicas, artísticas, populares, empíricas, ancestrales, etc.) y las aplico de manera crítica y creativa en función de la necesidad y los contextos.'),
(144, 3, 4, 44, 'Planifico y administro responsablemente mis recursos, de forma ética.'),
(145, 3, 4, 45, 'Establezco prioridades en las tareas administrando el uso del tiempo y los recursos disponibles para lograr los objetivos.'),
(146, 3, 4, 46, 'Encuentro momentos para descansar, distenderme, compartir con mis amistades y disfrutar de mi tiempo libre.'),
(147, 3, 4, 47, 'Actúo de manera resiliente ante las dificultades, buscando la superación personal y colectiva.'),
(148, 3, 4, 48, 'Desarrollo habilidades para comunicarme de forma efectiva y respetuosa, influyendo positivamente en mi entorno y en la sociedad en general.'),
(149, 3, 4, 49, 'Utilizo diferentes herramientas y tecnologías de comunicación para llegar a un público más amplio y diverso, promoviendo el diálogo y la colaboración entre las personas.'),
(150, 4, 5, 1, 'Sostengo y promuevo hábitos de higiene y alimentación saludables.'),
(151, 4, 5, 2, 'Disfruto y participo de las actividades recreativas, lúdicas, físicas y deportivas, buscando mi bienestar integral.'),
(152, 4, 5, 3, 'Organizo y administro el tiempo y los recursos disponibles para alcanzar mis metas.'),
(153, 4, 5, 4, 'Disfruto de las oportunidades y experiencias que brinda la vida en la naturaleza.'),
(154, 4, 5, 5, 'Evalúo situaciones y busco evitar conductas que me expongan a peligros a mí o a otras personas.'),
(155, 4, 6, 1, 'Exploro mis intereses vocacionales, descubro mis posibilidades y elijo en consecuencia.'),
(156, 4, 6, 2, 'Aplico técnicas y tecnologías de la información disponibles en la vida cotidiana.'),
(157, 4, 6, 3, 'Busco y evalúo el valor de diversas fuentes de información (académicas, científicas, artísticas, populares, empíricas, ancestrales, etc.) y las aplico de manera crítica y creativa en función de la necesidad y los contextos.'),
(158, 4, 6, 4, 'Me posiciono crítica y responsablemente ante los mensajes que los medios de comunicación y redes sociales instalan sobre el cuerpo humano y sus estereotipos.'),
(159, 4, 7, 1, 'Contribuyo pacíficamente a la resolución de conflictos evitando toda forma de intolerancia y violencia, promoviendo la paz.'),
(160, 4, 7, 2, 'Me comunico de manera asertiva y comprensible utilizando diferentes formatos y medios con una mirada inclusiva.'),
(161, 4, 7, 3, 'Escucho activamente y valoro las opiniones y sentimientos de las demás personas construyendo relaciones basadas en el respeto y la empatía.'),
(162, 4, 7, 4, 'Tomo conciencia de mis emociones y las expreso comprendiendo como impactan en mí y en mi entorno.'),
(163, 4, 7, 5, 'Reconozco, acepto y valoro mi cuerpo y el de los demás en su integralidad.'),
(164, 4, 7, 6, 'Vivo mi sexualidad de manera plena y consciente cuidando mis relaciones sexoafectivas de manera sana y segura.'),
(165, 4, 7, 7, 'Analizo y cuestiono actitudes y estereotipos culturales entendiendo cómo éstas pueden perpetuar la discriminación y exclusión.'),
(166, 4, 8, 1, 'Me responsabilizo por mi desarrollo personal, esforzándome por superarme constantemente.'),
(167, 4, 8, 2, 'Desarrollo habilidades para el mundo laboral.'),
(168, 4, 8, 3, 'Tomo decisiones económicas (y financieras) que acompañen mi proyecto de vida de manera consciente y responsable.'),
(169, 4, 8, 4, 'Actúo de manera resiliente ante las dificultades, buscando la superación personal y colectiva.'),
(170, 4, 9, 1, 'Valoro mi identidad y promuevo la herencia cultural, rescatando los saberes ancestrales de mi comunidad y de mi país.'),
(171, 4, 9, 2, 'Promuevo y defiendo los Derechos Humanos.'),
(172, 4, 9, 3, 'Ejercito plena y responsablemente mis derechos como ciudadano/a en todos los ámbitos de desarrollo con una mirada crítica de la realidad.'),
(173, 4, 9, 4, 'Defiendo y promuevo el respeto a las reglas de la democracia, aportando a su construcción a partir de una mirada crítica de la realidad.'),
(174, 4, 9, 5, 'Miro al mundo desde una perspectiva de derechos, viviendo y promoviendo colectivamente una experiencia integral, igualitaria y segura.'),
(175, 4, 9, 6, 'Valoro la diversidad y promuevo la inclusión en todos los ámbitos en los que me desempeño.'),
(176, 4, 9, 7, 'Me involucro, planifico y desarrollo acciones comunitarias que sean sostenibles y tengan un impacto socioambiental positivo.'),
(177, 4, 9, 8, 'Valoro y promuevo la solidaridad, la empatía y el compromiso social como formas esenciales de vivir junto a las demás personas.'),
(178, 4, 9, 9, 'Indago en las causas y consecuencias de las injusticias, desigualdades y problemáticas sociales, actuando comprometida y coherentemente para la construcción de una sociedad cada vez más justa, equitativa e igualitaria.'),
(179, 4, 9, 10, 'Consumo y produzco de manera sostenible y sustentable.'),
(180, 4, 9, 11, 'Desarrollo acciones de preservación y protección ambiental a partir de una conciencia crítica y responsable de las causas y consecuencias del impacto ambiental.'),
(181, 4, 9, 12, 'Reconozco la interdependencia entre las personas y todas las especies desarrollando el cuidado de la madre tierra.'),
(182, 4, 9, 13, 'Reconozco que la Tierra es nuestra casa común y promuevo la armonía con la naturaleza, a favor de un equilibrio justo entre las necesidades económicas, sociales y ambientales de las generaciones actuales y futuras.'),
(183, 4, 10, 1, 'Me cuestiono sobre las grandes preguntas que dan sentido a la existencia.'),
(184, 4, 10, 2, 'Promuevo el diálogo y el entendimiento más allá de las creencias personales.'),
(185, 4, 10, 3, 'Asumo un estilo de vida en coherencia con mis creencias y valores.'),
(186, 4, 10, 4, 'Valoro la naturaleza como una oportunidad de conexión conmigo mismo y con lo trascendente.');
